import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand


class UeS1CtxRelease(GenericEPCSIMCommand):
    """Command ue_s1_ctx_release."""

    def __init__(self, connection, id_option, prompt=None, newline_chars=None, runner=None):
        """
        Command ue_s1_ctx_release.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(UeS1CtxRelease, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.id_option = id_option
        self.brace = 0
        self.value = None
        self.value2 = None
        self.value3 = None
        self.value4 = 0
        self.value5 = None

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"ue_s1_ctx_release id={self.id_option}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_brace_open(line)
                self._parse_brace_close(line)
                self._parse_lines(line)
            except ParsingDone:
                pass
        return super(UeS1CtxRelease, self).on_new_line(line, is_full_line)

    # Error: ../src/linux/gate/cmds/invoker/src/Invoker.cpp:596: Command ue_s1_ctx_release is disabled currently
    _re_error = re.compile(r"^Error:\s+(?P<ERROR>.*)")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(UeS1CtxRelease._re_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    # value S1AP-PDU ::= initiatingMessage :
    _re_lines = re.compile(r"^(\s*value\s+)?\s*(?P<LINE>.+?(?=\s:\s?$|,|$|\s$))")

    def _parse_lines(self, line):
        if self._regex_helper.search_compiled(UeS1CtxRelease._re_lines, line):
            if self.brace == 0:
                self.current_ret[self._regex_helper.group("LINE")] = {}
                self.value = self._regex_helper.group("LINE")
            elif self.brace == 1:
                self.current_ret[self.value][self._regex_helper.group("LINE")] = {}
                self.value2 = self._regex_helper.group("LINE")
            elif self.brace == 2:
                self.current_ret[self.value][self.value2][self._regex_helper.group("LINE")] = {}
                self.value3 = self._regex_helper.group("LINE")
            elif self.brace == 4:
                self.current_ret[self.value][self.value2][self.value3][self.value4][self._regex_helper.group("LINE")] = {}
                self.value5 = self._regex_helper.group("LINE")
            elif self.brace == 5:
                self.current_ret[self.value][self.value2][self.value3][self.value4][self.value5] = [self._regex_helper.group("LINE")]
            raise ParsingDone

    #     {
    _re_brace_open = re.compile(r"^\s*{$")

    def _parse_brace_open(self, line):
        if self._regex_helper.search_compiled(UeS1CtxRelease._re_brace_open, line):
            self.brace = self.brace + 1
            if self.brace == 4:
                self.value4 = self.value4 + 1
                self.current_ret[self.value][self.value2][self.value3][self.value4] = {}
            raise ParsingDone

    #       },
    _re_brace__close = re.compile(r"^\s*},?$")

    def _parse_brace_close(self, line):
        if self._regex_helper.search_compiled(UeS1CtxRelease._re_brace__close, line):
            self.brace = self.brace - 1
            if self.brace == 2:
                self.value4 = 0
            raise ParsingDone


